#pragma once

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "esp_err.h"
#include "cJSON.h"
#include "esp_http_server.h"
#include "hy/api.h"
#include "hy/routes.h"
#include "hy/web.h"

/* ---- static assets (generated by tools/web_bundle.py into the build directory) ---- */

typedef struct {
    const char *path;      /* "/index.html", "/app.<hash>.js", ... */
    const char *mime;
    const uint8_t *gz;     /* gzip */
    size_t len;
    bool immutable;        /* hashed name: max-age one year, immutable; else no-cache */
} hy_web_asset_t;

extern const hy_web_asset_t hy_web_assets[];
extern const size_t hy_web_assets_n;
extern const size_t hy_web_assets_bytes;

/* ---- one /api request, as the route handlers see it ---- */

#define WEB_BODY_MAX (16 * 1024)

/* Header buffers, shared by /api and /ws so both accept the same requests. A longer value is treated as absent. */
#define WEB_HDR_HOST   72
#define WEB_HDR_ORIGIN 128
#define WEB_HDR_COOKIE 512

typedef struct {
    httpd_req_t *req;
    const hy_route_t *route;
    uint32_t id;           /* the "{id}" segment, 0 when the route has none */
    char *body;            /* NUL-terminated, PSRAM; "" when the request has none; freed by the dispatcher */
    size_t body_len;
    int sess;              /* session slot of the caller, -1 when unpaired */
    int status;            /* set by the web_send_* helpers */
} web_req_t;

typedef esp_err_t (*web_handler_t)(web_req_t *r);

/* "Cache-Control: no-store" and the JSON type are set on every answer. */
esp_err_t web_send_json(web_req_t *r, int status, const char *json);
/* {"error":"<code>","field":..,"message":..}; field and message may be NULL */
esp_err_t web_send_err(web_req_t *r, int status, const char *code, const char *field, const char *message);
/* hy_api_err_from mapping */
esp_err_t web_send_hy_err(web_req_t *r, hy_err_t e, const char *message);
/* 503 "busy" with Retry-After 2: a job timed out */
esp_err_t web_send_busy(web_req_t *r);
/* A refusal from a handler that reads its own body (import, firmware update): the error answer (Retry-After 2 on a
 * 503), then ESP_FAIL when more than 16 KB of body is unread so the socket closes, else ESP_OK */
esp_err_t web_refuse(web_req_t *r, int status, const char *code, const char *field, const char *msg);
const char *web_status_line(int status);

/* Route handlers. h_core.c answers info, state, pairing and browsers, then asks each family below; NULL from all of
 * them: 501 "not_implemented". The families are weak in h_core.c (NULL) and defined by their own files; the component
 * links as a whole archive so a strong definition always wins. */
web_handler_t web_route_handler(hy_route_id_t id);
web_handler_t web_meds_route(hy_route_id_t id);       /* medicines, pills, dose actions */
web_handler_t web_log_route(hy_route_id_t id);        /* log, history, schedule */
web_handler_t web_settings_route(hy_route_id_t id);   /* settings, time, chime, power off */
web_handler_t web_wifi_route(hy_route_id_t id);       /* Wi-Fi */
web_handler_t web_data_route(hy_route_id_t id);       /* export, import, firmware update */
web_handler_t web_update_route(hy_route_id_t id);     /* firmware update from GitHub (h_update.c) */
web_handler_t web_cabinet_route(hy_route_id_t id);    /* cabinet open (h_cabinet.c) */
/* Subscribes once to the update status; each change goes out as a live event (h_update.c, at server start) */
void web_update_start(void);

/* Export and import (h_backup.c). busy: an import is writing, other web writes answer 409 "busy". stop: refuses new
 * exports and imports, asks a running one to end and waits for it however long (server stop, before httpd_stop).
 * allow: accepts them again (after httpd_stop). */
bool web_backup_busy(void);
void web_backup_stop(void);
void web_backup_allow(void);
/* The server is stopping: a running worker ends at its next step (worker task) */
bool web_backup_aborting(void);

/* Firmware update (h_ota.c). The handler checks the request in the httpd task, then web_ota_start detaches it to the
 * backup worker slot (409 "busy" while an export, import or another upload runs), which calls web_ota_run with the
 * async request. restarting: an image was written and the device restarts shortly; new uploads, exports and imports
 * answer busy. */
esp_err_t web_ota_handler(web_req_t *r);
esp_err_t web_ota_start(web_req_t *r, size_t len);
void      web_ota_run(httpd_req_t *req, size_t len);
bool      web_ota_restarting(void);

/* Host name, IP literals and AP mode of the moment (hy_net_status copy). */
typedef struct {
    bool ap;
    char ip[16];
    char host[33];
} web_net_t;
void web_net_now(web_net_t *out);

/* ---- UI side (server.c) ---- */

/* Runs the registered callback in the LVGL task. Text arguments must be static. */
void web_ui_pair_hide(int reason);
void web_ui_toast_ok(const char *text);
/* The open settings views redraw their values (a setting-like state changed behind the screen's back) */
void web_ui_settings_refresh(void);
void web_ui_toast_info(const char *text);
/* Calls the registered power_off callback in the LVGL task (hy_power_off() when none is registered). false when it
 * could not be queued (LVGL busy): the caller retries. */
bool web_ui_power_off(void);
/* esp_restart in the LVGL task, so no store write is cut halfway; false when it could not be queued */
bool web_ui_restart(void);
/* The registered callbacks or NULL; read it only from the LVGL task */
const hy_web_ui_t *web_ui(void);

/* ---- pairing state (h_core.c) ---- */

void web_pair_init(void);
/* Under the pairing lock: the running code and its expiry, false when none runs */
bool web_pair_peek(char code[7], int64_t *expires_mono);

/* ---- sessions (session.c) ---- */

#define WEB_SESS_MAX 4
#define WEB_LABEL_LEN 24

typedef struct {
    int slot;
    int64_t created;       /* wall clock seconds, 0 when the clock was invalid */
    char label[WEB_LABEL_LEN];
} web_sess_info_t;

esp_err_t web_sess_init(void);
/* The slot whose stored SHA-256 matches the hy_s cookie of the Cookie header (constant time over every slot), or -1.
 * *gen (may be NULL) receives the slot's generation, which changes whenever the slot is replaced or forgotten. */
int       web_sess_check(const char *cookie_header, uint32_t *gen);
/* Stores the hash of token (32 bytes) with a label from the User-Agent. A fifth browser replaces the oldest. */
esp_err_t web_sess_add(const uint8_t token[32], const char *user_agent, int *slot);
size_t    web_sess_list(web_sess_info_t *out, size_t max);
/* slot -1: all */
esp_err_t web_sess_forget(int slot);
size_t    web_sess_count(void);
bool      web_sess_valid(int slot, uint32_t gen);
/* SHA-256 through PSA */
esp_err_t web_sha256(const uint8_t *in, size_t len, uint8_t out[32]);

/* ---- WebSocket (ws.c) ---- */

void      web_ws_init(void);
/* After httpd_start / before httpd_stop */
void      web_ws_attach(httpd_handle_t srv);
void      web_ws_detach(void);
esp_err_t web_ws_register(httpd_handle_t srv);
/* httpd close_fn hook */
void      web_ws_on_close(int fd);
/* Any task: queues one message (under 192 bytes) for the open live-event sockets, in the ring the bus events use */
void      web_ws_push(const char *json);
/* Closes live-event sockets whose session was forgotten (queued to the httpd task) */
void      web_ws_sessions_changed(void);
/* Queues fn to the httpd task when the server runs; false otherwise */
bool      web_queue_work(httpd_work_fn_t fn, void *arg);
#if CONFIG_HY_DEBUG_CONSOLE
void      web_ws_debug(void);
#endif

/* ---- host check shared by the handlers (server.c) ---- */

/* true when the Host header is allowed; else sends 302 to the portal (AP mode) or 421 and returns false. api: JSON
 * error body with no-store. */
bool web_host_check(httpd_req_t *req, const web_net_t *net, bool api);

/* ---- REST helpers (h_util.c) ---- */

#include "bridge.h"
#include "hy/store.h"

/* A job whose context starts with "const char *body" (set to a private copy of the request body, valid as long as the
 * job runs, which can outlive the handler after a timeout) followed by the handler's own fields. ctx_size covers the
 * whole struct. NULL on no memory. */
hy_job_t *web_job_new(web_req_t *r, void (*fn)(void *), size_t ctx_size);
/* hy_job_run on a job from web_job_new, after the handler filled its input fields in the context. Returns the
 * context; on a timeout the 503 busy answer is already sent in *sent, the job is released and NULL comes back.
 * Otherwise the caller reads the context and then calls hy_job_put(j). */
void *web_job_go(web_req_t *r, hy_job_t *j, uint32_t timeout_ms, esp_err_t *sent);
/* Result and scratch of web_settings_apply_json. The two integration copies may hold secrets: the helper wipes them
 * before it returns, and the caller keeps this struct in a job context (PSRAM), never on a stack. */
typedef struct {
    hy_api_err_t aerr;
    bool failed;            /* a body member was refused: nothing was saved */
    bool not_taught;        /* the mode was set to Taught movement and no movement is taught: nothing was saved */
    esp_err_t save;         /* the settings write */
    esp_err_t integ_save;   /* the integration write, ESP_OK when it did not change */
    hy_settings_t now;      /* the settings in force afterwards */
    hy_integ_t inow;        /* the integration settings in force afterwards, secrets replaced by "*" (set) or "" */
    hy_integ_t cur, next;   /* scratch */
} web_settings_t;
/* Merges a settings body (the settings members plus "mqtt" and "webhooks") onto the current values, saves what
 * changed and tells the device UI. LVGL task only (call it from a job). Nothing is saved when any member is refused. */
void web_settings_apply_json(const char *json, web_settings_t *res);
/* Out of memory: 503 "busy" with Retry-After, the answer the web UI retries on */
esp_err_t web_oom(web_req_t *r);

/* hy_api_err_from mapping with a readable message */
esp_err_t web_fail(web_req_t *r, hy_err_t e);
esp_err_t web_fail_api(web_req_t *r, const hy_api_err_t *e);
/* Prints o, deletes it and sends it; o NULL gives 500 */
esp_err_t web_send_cjson(web_req_t *r, int status, cJSON *o);
/* "{}" when the request has no body, so a body-less action parses as an empty object */
const char *web_body_or_empty(const web_req_t *r);
/* Value of a query parameter of the request URI, false when absent or longer than len - 1 */
bool web_query_get(const web_req_t *r, const char *key, char *out, size_t len);
/* The query string of the request URI without the "?", "" when none */
const char *web_query(const web_req_t *r);
/* hy_store query_log of one medicine (0 = all) keeping the newest entries: a full buffer narrows the window from its
 * old end until the answer fits (LVGL task) */
size_t web_log_window(uint32_t med_id, int64_t from, int64_t to, hy_log_t *out, size_t cap);

/* Growing PSRAM text buffer for answers too large for the stack */
typedef struct {
    char *p;
    size_t len, cap;
    bool bad;
} web_sb_t;
void web_sb_add(web_sb_t *b, const char *s, size_t n);
void web_sb_str(web_sb_t *b, const char *s);
void web_sb_fmt(web_sb_t *b, const char *fmt, ...) __attribute__((format(printf, 2, 3)));
/* A JSON string literal of s (quotes, backslash and control bytes escaped) */
void web_sb_jstr(web_sb_t *b, const char *s);
void web_sb_free(web_sb_t *b);
/* Sends the buffer as JSON (500 when it ran out of memory) and frees it */
esp_err_t web_sb_send(web_req_t *r, int status, web_sb_t *b);

/* YYYYMMDD as "YYYY-MM-DD" */
void web_date_str(int32_t ymd, char out[11]);
